from collections import Counter

def get_pairs(word):
    # already covered as adjacent symbol pairs in Byte Pair Encoding in this topic
    return list(zip(word[:-1], word[1:]))

words = [list("low") + ["</w>"], list("lower") + ["</w>"], list("lowest") + ["</w>"]]

for merge_step in range(3):
    # already covered as repeatedly merging the most frequent pair in this topic
    pair_counts = Counter()
    for word in words:
        for pair in get_pairs(word):
            pair_counts[pair] += 1

    best_pair = pair_counts.most_common(1)[0][0]
    merged_symbol = "".join(best_pair)
    print(f"Merge {merge_step + 1} (already covered as Byte Pair Encoding in this topic): {best_pair} -> '{merged_symbol}'")

    new_words = []
    for word in words:
        new_word, i = [], 0
        while i < len(word):
            if i < len(word) - 1 and (word[i], word[i+1]) == best_pair:
                new_word.append(merged_symbol)
                i += 2
            else:
                new_word.append(word[i])
                i += 1
        new_words.append(new_word)
    words = new_words

print(f"\nFinal subword pieces (already covered in this topic): {words}")
